class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows = len(grid)
        cols = len(grid[0])
        parity = 0
        for r in range(rows):
            if r % 2 == 0:
                col_range = range(cols)
            else:
                col_range = range(cols - 1, -1, -1)
            for c in col_range:
                if parity % 2 == 0:
                    result.append(grid[r][c])
                parity += 1
        return result

