        m = len(mana)

        prefix = [0] * n
        s = 0
        for i in range(n):
            s += skill[i]
            prefix[i] = s

        free = [0] * n

        for j in range(m):
            mj = mana[j]
            x = free[0]
            for i in range(1, n):
                cand = free[i] - prefix[i - 1] * mj
                if cand > x:
                    x = cand
            for i in range(n):
                free[i] = x + prefix[i] * mj

        return free[n - 1]

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        a = [ord(c) - 97 for c in s]

        D = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for j in range(26):
                d = abs(i - j)
                if d > 13:
                    d = 26 - d
                D[i][j] = d

        cap = min(k, 26)

        # cache for endpoint-pair costs and derived tables
        cache = {}

        def endpoint_info(x, y):
            key = (x, y)
            info = cache.get(key)
            if info is not None:
                return info
            costs = [D[x][t] + D[y][t] for t in range(26)]
            min_all = min(costs)
            min_le = [None] * (cap + 1)
            for c in costs:
                if c > cap:
                    continue
                for u in range(c, cap + 1):
                    if min_le[u] is None or c < min_le[u]:
                        min_le[u] = c
            info = (min_all, min_le)
            cache[key] = info
            return info

        dp = [[None] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                x = a[l]
                y = a[r]
                min_all, min_le = endpoint_info(x, y)

                inner = dp[l + 1][r - 1] if l + 1 <= r - 1 else None
                skip_l = dp[l + 1][r]
                skip_r = dp[l][r - 1]

                row = [0] * (k + 1)
                prev = None
                for u in range(k + 1):
                    best = skip_l[u]
                    v = skip_r[u]
                    if v > best:
                        best = v

                    mm = min_le[u] if u <= cap else min_all
                    if mm is not None:
                        idx = u - mm
                        if inner is None:
                            cand = 2
                        else:
                            cand = 2 + inner[idx]
                        if cand > best:
                            best = cand

                    if prev is not None and prev > best:
                        best = prev
                    row[u] = best
                    prev = best

                dp[l][r] = row

        return dp[0][n - 1][k]

