class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)

        P = [0] * (n + 1)
        C = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
            C[i + 1] = C[i] + cost[i]

        best = P[n] * C[n] + k * C[n]
        prev = [0] * (n + 1)  # prev[i] = dp[i][m-1] - P[i]*C[i] - k*(m-1)*C[i]

        for m in range(2, n + 1):
            a = [0] * (n + 1)
            s = [0] * (n + 1)
            dq = deque()
            curr = [0] * (n + 1)

            for j in range(1, n + 1):
                if j >= m:
                    x = P[j]
                    while len(dq) >= 2:
                        f = dq[0]
                        g = dq[1]
                        if a[g] + s[g] * x <= a[f] + s[f] * x:
                            dq.popleft()
                        else:
                            break
                    curr[j] = a[dq[0]] + s[dq[0]] * x

                if j >= m - 1 and j < n:
                    a[j] = prev[j] + (P[j] - k) * C[j]
                    s[j] = -C[j]
                    while len(dq) >= 2:
                        b = dq[-2]
                        c = dq[-1]
                        lhs = (a[c] - a[b]) * (s[c] - s[j])
                        rhs = (a[j] - a[c]) * (s[b] - s[c])
                        if lhs >= rhs:
                            dq.pop()
                        else:
                            break
                    dq.append(j)

            total = P[n] * C[n] + k * m * C[n] + curr[n]
            if total < best:
                best = total
            prev = curr

        return best

