class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # DP over (parity, sum) -> set of achievable products.
        # parity = index parity of the NEXT element in the subsequence
        # (0 = next element goes at an even position).
        # sum = alternating sum of the subsequence so far.
        # Products are tracked exactly as long as they are <= limit.
        # A single marker (limit + 1) represents "product > limit".
        # This marker is only needed so that a later 0 can reset the
        # product to 0 (0 <= limit).

        # empty state: no elements taken yet
        empty = {(0, 0): {1}}
        nonempty = {}  # (parity, sum) -> set of products

        for x in nums:
            new_nonempty = {}

            # persist states that do NOT take x (copy-on-write friendly)
            for key, prods in nonempty.items():
                new_nonempty[key] = prods

            # take x from empty state
            for (p, s), prods in empty.items():
                np_ = 1 - p
                ns = s + (x if p == 0 else -x)
                for prod in prods:
                    nprod = prod * x
                    if nprod <= limit:
                        key = (np_, ns)
                        if key in new_nonempty:
                            new_nonempty[key] = set(new_nonempty[key])
                            new_nonempty[key].add(nprod)
                        else:
                            new_nonempty[key] = {nprod}
                    else:
                        key = (np_, ns)
                        if key in new_nonempty:
                            new_nonempty[key] = set(new_nonempty[key])
                            new_nonempty[key].add(limit + 1)
                        else:
                            new_nonempty[key] = {limit + 1}

            # take x from nonempty states
            for (p, s), prods in nonempty.items():
                np_ = 1 - p
                ns = s + (x if p == 0 else -x)
                for prod in prods:
                    nprod = prod * x
                    key = (np_, ns)
                    if nprod <= limit:
                        if key in new_nonempty:
                            new_nonempty[key] = set(new_nonempty[key])
                            new_nonempty[key].add(nprod)
                        else:
                            new_nonempty[key] = {nprod}
                    else:
                        if key in new_nonempty:
                            new_nonempty[key] = set(new_nonempty[key])
                            new_nonempty[key].add(limit + 1)
                        else:
                            new_nonempty[key] = {limit + 1}

            nonempty = new_nonempty

        ans = -1
        for (p, s), prods in nonempty.items():
            if s == k:
                for prod in prods:
                    if prod <= limit and prod > ans:
                        ans = prod
        return ans

