class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        n = len(points)
        if k > n:
            return 0

        # Parameterize boundary by t in [0, 4s].
        # sid: 0=bottom, 1=right, 2=top, 3=left
        # u: along-side coordinate in [0, s]
        data = []
        for (x, y) in points:
            if y == 0:
                sid = 0; u = x; t = u
            elif y == s:
                sid = 2; u = x; t = 3 * s - u
            elif x == 0:
                sid = 3; u = y; t = 4 * s - u
            else:
                sid = 1; u = y; t = s + u
            data.append((t, sid, u))
        data.sort(key=lambda z: z[0])
        ts = [d[0] for d in data]
        sids = [d[1] for d in data]
        us = [d[2] for d in data]

        def forbidden_intervals(idx, d):
            sid = sids[idx]; u = us[idx]
            intervals = []

            def add(tgt_sid, lo, hi):
                if hi <= lo:
                    return
                lo = max(lo, 0); hi = min(hi, s + 1)
                if hi <= lo:
                    return
                if tgt_sid == 0:      # bottom: t = u
                    intervals.append((lo, hi))
                elif tgt_sid == 1:    # right: t = s + u
                    intervals.append((s + lo, s + hi))
                elif tgt_sid == 2:    # top: t = 3s - u
                    intervals.append((3 * s - hi + 1, 3 * s - lo + 1))
                else:                 # left: t = 4s - u
                    intervals.append((4 * s - hi + 1, 4 * s - lo + 1))

            for tgt in range(4):
                if tgt == sid:
                    add(tgt, u - d + 1, u + d)
                elif sid == 0:  # p bottom
                    if tgt == 1:      # right: (s - u_p) + u_q < d
                        add(tgt, 0, d - s + u)
                    elif tgt == 2:    # top: |u_p - u_q| + s < d
                        if d > s:
                            add(tgt, u - (d - s) + 1, u + (d - s))
                    else:            # left: u_p + u_q < d
                        add(tgt, 0, d - u)
                elif sid == 1:  # p right
                    if tgt == 0:      # bottom: (s - u_q) + u_p < d
                        add(tgt, s + u - d + 1, s + 1)
                    elif tgt == 2:    # top: (s - u_q) + (s - u_p) < d
                        add(tgt, 2 * s - u - d + 1, s + 1)
                    else:            # left: s + |u_p - u_q| < d
                        if d > s:
                            add(tgt, u - (d - s) + 1, u + (d - s))
                elif sid == 2:  # p top
                    if tgt == 0:      # bottom: |u_p - u_q| + s < d
                        if d > s:
                            add(tgt, u - (d - s) + 1, u + (d - s))
                    elif tgt == 1:    # right: (s - u_q) + (s - u_p) < d
                        add(tgt, 2 * s - u - d + 1, s + 1)
                    else:            # left: u_p + (s - u_q) < d
                        add(tgt, u + s - d + 1, s + 1)
                else:  # p left
                    if tgt == 0:      # bottom: u_p + u_q < d
                        add(tgt, 0, d - u)
                    elif tgt == 1:    # right: s + |u_p - u_q| < d
                        if d > s:
                            add(tgt, u - (d - s) + 1, u + (d - s))
                    else:            # top: u_q + (s - u_p) < d
                        add(tgt, 0, d - s + u)
            return intervals

        def feasible(d):
            if d <= 0:
                return True
            forbidden = [None] * n

            def get_forbidden(i):
                if forbidden[i] is None:
                    forbidden[i] = forbidden_intervals(i, d)
                return forbidden[i]

            chosen = []

            def dfs(pos):
                if len(chosen) == k:
                    return True
                need = k - len(chosen)
                if n - pos < need:
                    return False

                ivs = []
                for ci in chosen:
                    ivs.extend(get_forbidden(ci))
                ivs.sort(key=lambda x: x[0])
                merged = []
                for lo, hi in ivs:
                    if merged and lo <= merged[-1][1]:
                        if hi > merged[-1][1]:
                            merged[-1] = (merged[-1][0], hi)
                    else:
                        merged.append((lo, hi))

                complement = []
                cur = ts[pos]
                for lo, hi in merged:
                    if hi <= cur:
                        continue
                    if lo > cur:
                        complement.append((cur, lo))
                    if hi > cur:
                        cur = hi
                if cur <= 4 * s:
                    complement.append((cur, 4 * s + 1))

                avail = 0
                for clo, chi in complement:
                    l = bisect_left(ts, clo)
                    if l < pos:
                        l = pos
                    r = bisect_left(ts, chi)
                    if r > l:
                        avail += r - l
                if avail < need:
                    return False

                for clo, chi in complement:
                    l = bisect_left(ts, clo)
                    if l < pos:
                        l = pos
                    r = bisect_left(ts, chi)
                    for j in range(l, r):
                        chosen.append(j)
                        if dfs(j + 1):
                            return True
                        chosen.pop()
                return False

            return dfs(0)

        lo, hi = 0, 2 * s
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # previous index with value <= current (for min)
        prev_le = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            if stack:
                prev_le[i] = stack[-1]
            stack.append(i)

        # previous index with value >= current (for max)
        prev_ge = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            if stack:
                prev_ge[i] = stack[-1]
            stack.append(i)

        # next index with value < current (strictly, for min)
        next_lt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                next_lt[i] = stack[-1]
            stack.append(i)

        # next index with value > current (strictly, for max)
        next_gt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_gt[i] = stack[-1]
            stack.append(i)

        def pairs(L0, R0, i):
            # count (l, r): L0 <= l <= i, i <= r <= R0, r - l + 1 <= k
            total = 0
            # Case A: l >= R0 - k + 1  =>  r may reach R0
            a = R0 - k + 1
            if a < L0:
                a = L0
            if a <= i:
                total += (i - a + 1) * (R0 - i + 1)
            # Case B: i - k + 1 <= l <= R0 - k
            lo = i - k + 1
            if lo < L0:
                lo = L0
            hi = R0 - k
            if hi > i:
                hi = i
            if lo <= hi:
                cnt = hi - lo + 1
                sum_l = (lo + hi) * cnt // 2
                total += sum_l + (k - i) * cnt
            return total

        ans = 0
        for i in range(n):
            L0 = prev_le[i] + 1
            R0 = next_lt[i] - 1
            ans += nums[i] * pairs(L0, R0, i)
            L0 = prev_ge[i] + 1
            R0 = next_gt[i] - 1
            ans += nums[i] * pairs(L0, R0, i)
        return ans
